import zipfile, xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def get_cells(p):
    with zipfile.ZipFile(p) as z:
        root=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    cells={}
    for row in root.findall('m:sheetData/m:row', ns):
        r=int(row.get('r'))
        for c in row.findall('m:c', ns):
            cells[c.get('r')]=c.get('s')
    return cells
orig=get_cells('seed_collection_0091_inconsistent_color_3939_input.xlsx')
fixed=get_cells('seed_collection_0091_inconsistent_color_3939_fixed.xlsx')
print('orig cells',len(orig),'fixed cells',len(fixed))
for ref in sorted(set(orig)|set(fixed)):
    if orig.get(ref)!=fixed.get(ref):
        print('diff',ref,orig.get(ref),fixed.get(ref))
